{
  "title": "Discussion about living and working abroad in Slovakia, Austria, and other EU countries",
  "topics": [
    {
      "id": "expatriate-presence",
      "title": "Presence of group members abroad",
      "claims": [
        {
          "text": "Some participants live in Bratislava or elsewhere in Slovakia",
          "evidence": [1]
        },
        {
          "text": "One participant has acquaintances in Austria and Poland",
          "evidence": [3]
        },
        {
          "text": "Participant P3 knows at least two people in Austria",
          "evidence": [12, 13]
        },
        {
          "text": "P3 has been living in Austria since 17.11.2025",
          "evidence": [49]
        },
        {
          "text": "P1 has been in Slovakia for almost a year",
          "evidence": [43]
        }
      ]
    },
    {
      "id": "job-search-abroad",
      "title": "Job search experiences and advice",
      "claims": [
        {
          "text": "Finding a job abroad was difficult but succeeded within two months",
          "evidence": [17]
        },
        {
          "text": "LinkedIn is recommended for job hunting",
          "evidence": [18]
        },
        {
          "text": "Approximately 100 applications yielded only three interviews for P3",
          "evidence": [21]
        },
        {
          "text": "Local language requirement appears in 95% of vacancies",
          "evidence": [26]
        },
        {
          "text": "Some companies accept candidates with limited local language skills",
          "evidence": [29]
        },
        {
          "text": "Salary for P3's position was higher than expected, but they accepted the minimum offered",
          "evidence": [37]
        },
        {
          "text": "Typical language level demanded is B2, sometimes B1, rarely a certificate",
          "evidence": [46]
        }
      ]
    },
    {
      "id": "language-barrier",
      "title": "Language requirements and personal language learning",
      "claims": [
        {
          "text": "German is the primary language spoken in Austria, but English is also used",
          "evidence": [14, 15]
        },
        {
          "text": "P3 is currently learning Slovak to navigate daily life",
          "evidence": [47]
        },
        {
          "text": "P1 feels uncomfortable speaking Slovak and prefers English",
          "evidence": [45, 52]
        },
        {
          "text": "P1 suggests improving English through Discord channels",
          "evidence": [56, 57]
        }
      ]
    },
    {
      "id": "salary-expectations",
      "title": "Salary expectations and market differences",
      "claims": [
        {
          "text": "Salaries in Europe are generally higher than in Ukraine, but many ignore this",
          "evidence": [35]
        },
        {
          "text": "P3 believes the salary for their role was higher than the minimum but accepted the lowest offer",
          "evidence": [37]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Who lives in Bratislava or elsewhere in Slovakia and who has moved abroad?",
      "evidence": [1]
    },
    {
      "text": "Should I stay in Austria or consider moving to another country?",
      "evidence": [58, 60]
    }
  ]
}
